import type { ICtx, ScheduleHandle } from "@threenative/core";
import {
  CharacterBody3D,
  CollisionShape3D,
  type IPhysicsContext,
  NavigationAgent3D,
} from "@threenative/physics";
import { attachToBone } from "@threenative/core";
import { Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_RADIUS = 8;
const SIGHT_RADIUS = 10;
const SIGHT_DOT_THRESHOLD = 0.3;
const MOVE_SPEED = 3.2;
const FIRE_RANGE = 12;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly navAgent: NavigationAgent3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  playerInSight = false;
  #fireTimer = 0;
  #onFire: (origin: Vector3) => void;
  #scanHandle: ScheduleHandle | undefined;
  #patrolIndex = 0;
  #patrolPoints: Vector3[] = [];
  #chaseTarget: Vector3 | undefined;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    patrolPoints: Vector3[] = [],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 60;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position.clone()];

    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.45, 0.38),
    });

    this.navAgent = new NavigationAgent3D({
      object: this.mesh,
      physics: ctx.physics,
    });

    this.#moveToPatrolPoint();
  }

  #moveToPatrolPoint(): void {
    const point = this.#patrolPoints[this.#patrolIndex % this.#patrolPoints.length];
    if (point !== undefined) {
      this.#chaseTarget = undefined;
      this.navAgent.moveTo(point);
    }
  }

  #getPlayerAimOrigin(): Vector3 {
    return this.mesh.position.clone().add(new Vector3(0, 0.72, -0.72));
  }

  startScanning(ctx: GameCtx, playerBodyId: number, playerAimOrigin: () => Vector3): void {
    const scan = (): void => {
      if (!this.alive) return;

      const scanShape = CollisionShape3D.sphere(SIGHT_RADIUS);
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 1,
        position: this.mesh.position,
        shape: scanShape,
      });

      const playerInRange = hits.some((hit) => hit.body.id === playerBodyId);

      if (playerInRange) {
        const playerPos = playerAimOrigin();
        const dirToPlayer = playerPos.clone().sub(this.mesh.position).normalize();
        const enemyForward = new Vector3(0, 0, -1);
        this.mesh.getWorldQuaternion({ x: 0, y: 0, z: 0, w: 1 } as any);
        const dot = dirToPlayer.dot(enemyForward);

        if (dot > SIGHT_DOT_THRESHOLD) {
          const rayHit = directSpaceState(ctx.physics).intersectRay({
            collisionMask: PLAYER_LAYER,
            from: this.mesh.position.clone().add(new Vector3(0, 0.5, 0)),
            to: playerPos,
          });
          this.playerInSight = rayHit?.body.id === playerBodyId;
        } else {
          this.playerInSight = false;
        }
      } else {
        this.playerInSight = false;
      }

      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
    if (!this.alive) return;

    if (this.playerInSight) {
      this.#chaseTarget = playerPos.clone();
      const distToPlayer = this.mesh.position.distanceTo(playerPos);
      if (distToPlayer > FIRE_RANGE) {
        this.navAgent.moveTo(playerPos);
      }
    } else if (this.#chaseTarget === undefined) {
      if (!this.navAgent.isNavigating()) {
        this.#patrolIndex += 1;
        this.#moveToPatrolPoint();
      }
    } else {
      this.#chaseTarget = undefined;
      this.#moveToPatrolPoint();
    }

    this.navAgent.update(dt);
    const velocity = this.navAgent.velocity;
    if (velocity !== undefined) {
      this.body.velocity.copy(velocity);
    }
    this.body.velocity.y = Math.max(this.body.velocity.y, -9.81 * dt);
    this.body.moveAndSlide(dt);

    if (this.playerInSight) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = 1.5;
        this.#onFire(this.#getPlayerAimOrigin());
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      health: this.health,
      playerInSight: this.playerInSight,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.navAgent.dispose();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

