        this.playerInSight = false;
      }

      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerPos: Vector3): void {
    if (!this.alive) return;

    let targetPos = this.#targetPoint;

    if (this.playerInSight) {
      this.#chaseTimer = 2;
      targetPos = playerPos.clone();
    } else if (this.#chaseTimer > 0) {
      this.#chaseTimer -= dt;
      targetPos = playerPos.clone();
    } else {
      targetPos = this.#targetPoint;
    }

    if (targetPos === undefined) {
      targetPos = this.#getNextPatrolPoint();
    }

    const direction = targetPos.clone().sub(this.mesh.position);
    const distance = direction.length();

    if (distance < 0.5) {
      if (this.#chaseTimer <= 0) {
        this.#targetPoint = this.#getNextPatrolPoint();
      }
    } else {
      direction.normalize();
      this.body.velocity.x = direction.x * MOVE_SPEED;
      this.body.velocity.z = direction.z * MOVE_SPEED;
    }

    this.body.moveAndSlide(dt);

    if (this.playerInSight) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = 1.5;
        this.#onFire(this.#getEnemyAimOrigin());
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      health: this.health,
      playerInSight: this.playerInSight,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

