import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });

  await page.goto('http://localhost:5174/', { waitUntil: 'networkidle', timeout: 10000 });
  console.log('Game loaded');

  await page.waitForTimeout(3000);

  // Move forward to encounter the enemy
  await page.keyboard.press('ArrowUp');
  await page.waitForTimeout(800);
  await page.keyboard.press('ArrowUp');
  await page.waitForTimeout(800);

  await page.screenshot({ path: '/tmp/game-enemy-1.png' });
  console.log('Screenshot: Enemy area 1');

  // Move left
  await page.keyboard.press('ArrowLeft');
  await page.waitForTimeout(800);

  await page.screenshot({ path: '/tmp/game-enemy-2.png' });
  console.log('Screenshot: Enemy area 2 (moved left)');

  // Move right (past center)
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('ArrowRight');
  await page.waitForTimeout(1000);

  await page.screenshot({ path: '/tmp/game-enemy-3.png' });
  console.log('Screenshot: Enemy area 3 (moved right)');

  // Fire at enemy if visible
  await page.keyboard.press('KeyF');
  await page.waitForTimeout(500);

  await page.screenshot({ path: '/tmp/game-enemy-4.png' });
  console.log('Screenshot: After firing at enemy');

  await browser.close();
  console.log('Test complete');
})().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});
EOF
